private DataRow GetRowByGraduationResultID(int intGraduationResultID)
{
    DataTable dtbSearch = GetSearchData();
    int intRow;

    if (dtbSearch == null)
        return null;

    for (intRow = 0; intRow < dtbSearch.Rows.Count; intRow++)
    {
        if (Convert.ToInt32(dtbSearch.Rows[intRow]["GraduationResultID"]) == intGraduationResultID)
            return dtbSearch.Rows[intRow];
    }

    return null;
}

