protected void btnExportRow_Click(object sender, EventArgs e)
{
    if (!IsValidData(true))
        return;

    LinkButton lbtExport = sender as LinkButton;
    if (lbtExport == null)
        return;

    int intGraduationResultID;
    if (!Int32.TryParse(lbtExport.CommandArgument, out intGraduationResultID))
    {
        MsgBox.ShowError("Không xác định được bản ghi cần xuất!");
        return;
    }

    DataRow drwExport = GetRowByGraduationResultID(intGraduationResultID);
    if (drwExport == null)
    {
        MsgBox.ShowWarning("Không tìm thấy dữ liệu sinh viên để xuất!");
        return;
    }

    string strFilePrefix = String.Format("ChiTietVanBangTotNghiep_{0}",
        WebGlobal.FilterFileName(Convert.ToString(drwExport["StudentCode"])));

    OpenExportInNewTab(BuildExportDetailHtml(drwExport), strFilePrefix);
    LoadData();
}

